# Search all ASTs up to depth 2/3 AND conditionals for:
# 1) f_box(23, 4, 2, 1, 0) == 27
# 2) f_tri(23, 4, 2, 1, 0) == 19
# 3) max(7, f_box(f_tri(14, 53, 4, 2, 2), 601, 4, 3, 1)) == 89
# (Note since 89 != 7, if ◇ = max(a,b) then inner MUST equal 89! Also check if ◇ != max(a,b) could give 89!)

atoms = ["a", "b", "n", "i", "d", "0", "1", "2", "3", "4", "5", "10"]
lvl1 = set(atoms)
for x in atoms:
    lvl1.add(f"(-{x})")
    lvl1.add(f"abs({x})")
for x in atoms:
    for y in atoms:
        for op in ["+", "-", "*", "//", "%"]:
            lvl1.add(f"({x}{op}{y})")
        if y in ("2", "3", "n", "i", "d"):
            lvl1.add(f"({x}**{y})")
        lvl1.add(f"min({x},{y})")
        lvl1.add(f"max({x},{y})")

def ev(e, a, b, n, i, d):
    try:
        v = eval(e, {"__builtins__": {}}, {"a":a, "b":b, "n":n, "i":i, "d":d, "abs":abs, "min":min, "max":max})
        if isinstance(v, int) and not isinstance(v, bool) and abs(v) <= 10**9:
            return v
    except Exception:
        return None
    return None

import random
random.seed(99)
pts = [(random.randint(-50,60), random.randint(1,60), random.choice([2,3,4]), random.choice([1,2,3]), random.choice([0,1,2])) for _ in range(10)]
pts.append((23, 4, 2, 1, 0))
pts.append((14, 53, 4, 2, 2))

def dedup(exprs):
    reps = {}
    for e in sorted(exprs, key=len):
        sig = tuple(ev(e, *p) for p in pts)
        if None in sig: continue
        if sig not in reps:
            reps[sig] = e
    return list(reps.values())

